class TashkentDistrictBoundary {
  const TashkentDistrictBoundary({
    required this.locationId,
    required this.nameEn,
    required this.nameRu,
    required this.nameUz,
    required this.polygons,
  });

  final int locationId;
  final String nameEn;
  final String nameRu;
  final String nameUz;
  final List<TashkentDistrictBoundaryPolygon> polygons;
}

class TashkentDistrictBoundaryPolygon {
  const TashkentDistrictBoundaryPolygon({
    required this.outerRing,
    this.innerRings = const [],
  });

  final List<DistrictBoundaryPoint> outerRing;
  final List<List<DistrictBoundaryPoint>> innerRings;
}

class DistrictBoundaryPoint {
  const DistrictBoundaryPoint(this.latitude, this.longitude);

  final double latitude;
  final double longitude;
}
